from collections import OrderedDict
import sys

lines = sys.stdin.read().splitlines()
capacity = int(lines[0].strip())
cache = OrderedDict()
out = []
for line in lines[1:]:
    parts = line.split()
    if not parts:
        continue
    if parts[0] == 'put':
        k, v = parts[1], parts[2]
        if k in cache:
            cache.move_to_end(k)
        cache[k] = v
        if len(cache) > capacity:
            cache.popitem(last=False)
    elif parts[0] == 'get':
        k = parts[1]
        if k in cache:
            cache.move_to_end(k)
            out.append(cache[k])
        else:
            out.append('-1')
print('\n'.join(out))

